import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"革","description":"东坡易传 - 革","frontmatter":{"title":"革","description":"东坡易传 - 革"},"headers":[],"relativePath":"zh/classics/dongpo/050.md","filePath":"zh/classics/dongpo/050.md"}'),o={name:"zh/classics/dongpo/050.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="革" tabindex="-1">革 <a class="header-anchor" href="#革" aria-label="Permalink to “革”">​</a></h1><p>“革”：巳日乃孚，元亨利貞，悔亡。</p><p>《彖》曰：“革”，水火相息，二女同居，其志不相得，曰：“革”。“巳曰乃孚”革而信之；文明以說，大亨以正；革而當，其悔乃亡。</p><p>水、火，則有男女之象然後能相生，此非水、火也。“二女同居”而已。“二女同居”則“睽”，所以不“睽”者，“兌”欲下而遇“離”，“離”欲上而遇“兌”，雖欲相違而不能也。既不相得，又不相違，則不能無相攻；攻而不已，必有一勝；勝者斯“革”之矣。火能革金，“離”革“兌”者也，故曰“革”。火者金之所畏也，而金非火則無以就器用，器成而後知火之利也。故夫“革”，不信於“革”之日，而信於已“革”之日，以其始之不信，是以知悔者“革”之所不能免也，特有以亡之爾。天地革而四時成；湯武革命，順乎天而應乎人。革之時大矣哉！象曰：澤中有火，“革”；君子以治歷明時。 “歷”者天事也；“時”者，人事也。</p><p>初九：鞏用黃牛之革。象曰：“鞏用黃牛”，不可以有爲也。</p><p>以卦言之，則“離”革“兌”者也；以爻言之，則陽革陰者也。六爻皆以陽革陰，故初九、九三、九四、九五四者所以革人；而六二、上六者人革之。初九、九三所以爲革者，火也；而六二者火之所附，初九、九三之所欲革者也。火以有所附爲利，而所附者以得火爲災，故初九、九三常願六二之留而不去也。夫六二苟留而不去，其見革也無日矣。六二之慾去，如“遯”之九三之慾遯也，故初九當用“遯”之六二，所以執九三者，固而留之。六二之所以去者，以我有革之之意也；故“不可以有爲”，有爲則革之之意見矣。</p><p>六二：巳日乃革之，徵吉，無咎。象曰：“巳日革之”，行有嘉也。</p><p>初九之所以固我，非愛我也，畏我去之；故未見其革爾。徒見其今之固我而不我革，以爲可信而與之處，則及矣。君子見幾而作，彼今日不革，巳日必革之，故“徵吉”。爲初九計，則宜留；自爲計，則宜徵。六二之所謂“嘉”者，五也；五之所以爲“革”者，與初異矣。舍初從五，其吉也，豈復有咎哉！</p><p>九三：徵兇，貞厲。革言三就，有孚。象曰：“革言三就”，又何之矣！</p><p>九三有應於上，故其意常欲徵也。六二之所以不得去者，以我乘之也；舍之而徵，則二去矣。二苟去之，則我與初九無所施其革，二陽相灼而喪其所附，則窮之道也。故“徵兇，貞厲”。貞者，不徵之謂也；不徵則與六二處而不相得以相革者也，故危。雖危而不兇，言者以也。“革言三就”，猶曰革以三成。三者相持而成革，明二之不可去也。二存則初與三相信，二去則初與三相疑，此必然之勢也。故曰：“革言三就，有孚。”</p><p>九四：悔亡，有孚；改命，吉。象曰：“改命”之“吉”，信志也。</p><p>下之二陽，以火爲革者也；故見革者惟欲去之，此德不足者也。德不足而革，則所革者亡，革者亦兇。故初九、九三，皆以六二之留爲吉也。上之二陽則不然，其革也以說。革而人莫不說，非有德者，其孰能之？九四，未當位者也；未當位而革，故悔革而說，故“悔亡，有孚”也。改命者始受命也，雖未當位，而志自信矣。</p><p>九五：大人虎變，未佔有孚。象曰：“大人虎變”，其文炳也。</p><p>《易》曰：“雲從龍，風從虎。”虎有文而能神者也，豹有文而不能神者也。故大人爲虎，君子爲豹。非大人而革者，皆毀人以自成，廢人以自興，故人之從之也，必佔其可從而後信。若大人之革也，則在我而已炳然日新，天下之所謂文者自廢矣，此豈待佔而後信者哉！</p><p>上六：君子豹變，小人革面，徵兇，居貞吉。象曰：“君子豹變”，其文蔚也；“小人革面”，順以從君也。</p><p>上六，見革於大人者也。此見革者君子也，則其向之未革，乃其避世之遇爾。豹生而有文，豈其無素而能爲之哉！若小人也，則革面而已。朝爲寇讎，莫爲腹心，無足怪者。下之二陽，德不足者也，故六二以徵爲吉；上之二陽，大人也；故上六以徵爲兇。</p>',16)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
